#!/usr/bin/env node
"use strict";

/**
 * MCP acceptance harness — Phase 0.2 discovery baseline.
 *
 * A standalone black-box harness that targets a configurable production-component
 * MCP endpoint and asserts the public OAuth discovery contract:
 *
 *   A1  an unauthenticated JSON-RPC `initialize` request receives HTTP 401
 *       (an OAuth challenge), not a protocol-dispatch error (e.g. HTTP 400
 *       with JSON-RPC -32601 "Method not found");
 *   A2  the 401 challenge carries a Bearer `WWW-Authenticate` header whose
 *       `resource_metadata` parameter is the configured public
 *       protected-resource metadata URL (the MCP endpoint origin plus
 *       `/.well-known/oauth-protected-resource`) and never a loopback or lab
 *       URL (e.g. `http://127.0.0.1:3001/...`);
 *   A3  the protected-resource metadata document parses as JSON and names the
 *       configured authorization-server issuer in `authorization_servers`;
 *   A4  the authorization-server metadata document parses as JSON and supplies
 *       usable `authorization_endpoint`, `token_endpoint`,
 *       `registration_endpoint`, and `jwks_uri` values (absolute http(s)
 *       URLs; https when the issuer is public).
 *
 * Baseline expectation (Phase 0.2): against the current production component,
 * A1, A2, and A4 FAIL and A3 passes. Verified current state (2026-09-17,
 * docs/MCP-PRODUCTION-FIX-PLAN.md):
 *   - `initialize` returns HTTP 400 with JSON-RPC -32601 (mcp-server/src/gateway.rs
 *     only recognizes tools/list and tools/call), so no 401 challenge is ever
 *     issued for the initial request;
 *   - the 401 builders that do exist hard-code the lab loopback URL
 *     `http://127.0.0.1:3001` (mcp-server/src/gateway.rs:456-541);
 *   - `https://mcal.hajnal.space/.well-known/oauth-protected-resource` is valid
 *     JSON advertising `https://cal.hajnal.space` (A3 passes);
 *   - `https://cal.hajnal.space/.well-known/openid-configuration` returns the
 *     CommonCal SPA HTML, not authorization-server metadata (A4 fails).
 *
 * The harness asserts the target contract and therefore exits non-zero against
 * the current production component. That failure is the intentional, asserted
 * exit condition for this phase: it documents the current broken state that
 * later phases must fix. The harness is a regression gate: it stays red until
 * the production component implements the public challenge and discovery.
 *
 * This harness does NOT launch or depend on the slice1-lab binaries, and it
 * does not treat the lab binary as a release artifact. It reuses the Phase 0.1
 * `initialize` request fixture (mcp-acceptance/fixtures/initialize-request.json)
 * and the MCP/OAuth standards-compliance expectations. It is a pure HTTP
 * client: it starts no servers and leaves no processes behind.
 *
 * Configuration (command-line flags, then environment variables, then defaults):
 *   --url / MCP_URL             MCP endpoint URL (default: https://mcal.hajnal.space/mcp)
 *   --issuer / MCP_OAUTH_ISSUER configured authorization-server issuer
 *                               (default: https://cal.hajnal.space)
 *   --timeout-ms / MCP_TIMEOUT_MS              request timeout ms (default: 15000)
 *   --record-dir / MCP_RECORD_DIR              record directory (default: OS temp dir)
 *
 * Exit codes:
 *   0  all discovery assertions pass (PASS)
 *   1  one or more discovery assertions fail (FAIL) — the intentional Phase 0.2
 *      baseline exit condition against the current production component
 *   2  harness error (invalid configuration, network failure, unexpected error)
 */

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const HARNESS_NAME = "commoncal-mcp-acceptance";
const HARNESS_VERSION = "0.2.0";

const DEFAULTS = {
  url: "https://mcal.hajnal.space/mcp",
  issuer: "https://cal.hajnal.space",
  timeoutMs: 15000,
};

class HarnessError extends Error {}

function env(name, fallback) {
  const v = process.env[name];
  return v === undefined || v === "" ? fallback : v;
}

/**
 * Parse command-line flags. Returns a map of flag -> value. Unknown flags are
 * collected under the `_unknown` key so they can be reported as a config error.
 */
function parseArgs(argv) {
  const flags = {};
  const unknown = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") {
      flags.help = true;
      continue;
    }
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      let name;
      let value;
      if (eq !== -1) {
        name = arg.slice(2, eq);
        value = arg.slice(eq + 1);
      } else {
        name = arg.slice(2);
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("--")) {
          value = next;
          i++;
        } else {
          value = "true";
        }
      }
      flags[name] = value;
    } else {
      unknown.push(arg);
    }
  }
  flags._unknown = unknown;
  return flags;
}

function printHelp() {
  console.log(`Usage: node mcp-acceptance/discovery.js [options]

Options:
  --url <url>              MCP endpoint URL (default: ${DEFAULTS.url})
  --issuer <url>           configured authorization-server issuer (default: ${DEFAULTS.issuer})
  --timeout-ms <n>         request timeout in ms (default: ${DEFAULTS.timeoutMs})
  --record-dir <dir>       directory for the deterministic record (default: OS temp dir)
  -h, --help               show this help

Environment variables MCP_URL, MCP_OAUTH_ISSUER, MCP_TIMEOUT_MS, and
MCP_RECORD_DIR are also honored; command-line flags take precedence.
`);
}

function describeError(err) {
  if (err === undefined || err === null) return "unknown error";
  if (typeof err === "string") return err;
  return err.message || String(err);
}

/**
 * Resolve a configuration value from (in order of precedence): command-line
 * flag, environment variable, default.
 */
function resolve(flags, flagName, envName, fallback) {
  if (flags[flagName] !== undefined) return flags[flagName];
  return env(envName, fallback);
}

function loadConfig(flags) {
  const url = resolve(flags, "url", "MCP_URL", DEFAULTS.url);
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new HarnessError(`MCP_URL is not a valid URL: ${url}`);
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new HarnessError(`MCP_URL must use http or https: ${url}`);
  }

  const issuer = resolve(flags, "issuer", "MCP_OAUTH_ISSUER", DEFAULTS.issuer);
  let issuerParsed;
  try {
    issuerParsed = new URL(issuer);
  } catch {
    throw new HarnessError(`MCP_OAUTH_ISSUER is not a valid URL: ${issuer}`);
  }
  if (issuerParsed.protocol !== "http:" && issuerParsed.protocol !== "https:") {
    throw new HarnessError(`MCP_OAUTH_ISSUER must use http or https: ${issuer}`);
  }

  const timeoutRaw = resolve(flags, "timeout-ms", "MCP_TIMEOUT_MS", String(DEFAULTS.timeoutMs));
  const timeoutMs = Number(timeoutRaw);
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    throw new HarnessError(`MCP_TIMEOUT_MS must be a positive number: ${timeoutRaw}`);
  }

  return {
    url,
    issuer,
    timeoutMs,
    recordDir: resolve(flags, "record-dir", "MCP_RECORD_DIR", os.tmpdir()),
  };
}

/**
 * The configured public protected-resource metadata URL: the MCP endpoint
 * origin plus the RFC 9728 well-known path. This mirrors the production
 * configuration logic (mcp-server/src/config.rs) and the fix-plan requirement
 * to derive resource_metadata from MCP_PUBLIC_RESOURCE_URL.
 */
function expectedResourceMetadataUrl(mcpUrl) {
  const u = new URL(mcpUrl);
  return `${u.origin}/.well-known/oauth-protected-resource`;
}

/**
 * True for loopback hosts: the 127.0.0.0/8 range, ::1, localhost, and 0.0.0.0.
 * The current production 401 builders hard-code the lab loopback URL
 * http://127.0.0.1:3001 (mcp-server/src/gateway.rs:456-541); this is the
 * "loopback or lab URL" the A2 assertion must reject.
 */
function isLoopbackHost(host) {
  if (!host) return false;
  const h = host.toLowerCase();
  if (h === "localhost" || h === "::1" || h === "0.0.0.0") return true;
  if (h === "127.0.0.1" || h.startsWith("127.")) return true;
  return false;
}

function isLoopbackUrl(rawUrl) {
  try {
    return isLoopbackHost(new URL(rawUrl).hostname);
  } catch {
    return false;
  }
}

/**
 * Load the `initialize` request fixture shared with the Phase 0.1 harness.
 */
function loadInitializeFixture() {
  const fixturePath = path.join(__dirname, "fixtures", "initialize-request.json");
  let raw;
  try {
    raw = fs.readFileSync(fixturePath, "utf8");
  } catch (err) {
    throw new HarnessError(
      `cannot read initialize fixture ${fixturePath}: ${describeError(err)}`
    );
  }
  let fixture;
  try {
    fixture = JSON.parse(raw);
  } catch (err) {
    throw new HarnessError(
      `initialize fixture ${fixturePath} is not valid JSON: ${describeError(err)}`
    );
  }
  if (
    !isPlainObject(fixture) ||
    fixture.method !== "initialize" ||
    !isPlainObject(fixture.params)
  ) {
    throw new HarnessError(
      `initialize fixture ${fixturePath} must be a JSON-RPC initialize request with params`
    );
  }
  return fixture;
}

function buildInitializeRequest() {
  const fixture = loadInitializeFixture();
  return {
    ...fixture,
    id: 1,
    params: {
      ...fixture.params,
      clientInfo: { name: HARNESS_NAME, version: HARNESS_VERSION },
    },
  };
}

/**
 * Perform one HTTP request and capture the full response deterministically.
 */
async function httpProbe(cfg, method, url, body) {
  const headers = {};
  let bodyString = null;
  if (body !== null && body !== undefined) {
    bodyString = typeof body === "string" ? body : JSON.stringify(body);
    headers["Content-Type"] = "application/json";
  }
  if (method === "POST") {
    headers.Accept = "application/json, text/event-stream";
  }

  let status;
  let respHeaders;
  let rawBody;
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), cfg.timeoutMs);
    let res;
    try {
      res = await fetch(url, {
        method,
        headers,
        body: bodyString,
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timer);
    }
    status = res.status;
    respHeaders = normalizeHeaders(res.headers);
    rawBody = await res.text();
  } catch (err) {
    throw new HarnessError(`network failure contacting ${url}: ${describeError(err)}`);
  }

  let bodyJson = null;
  let bodyJsonParseError = null;
  try {
    bodyJson = JSON.parse(rawBody);
  } catch (err) {
    bodyJsonParseError = describeError(err);
  }

  return {
    status,
    headers: respHeaders,
    bodyRaw: rawBody,
    bodyJson,
    bodyJsonParseError,
  };
}

/**
 * Normalize response headers into a plain object, dropping volatile /
 * hop-by-hop headers so the recorded response is deterministic.
 */
function normalizeHeaders(headers) {
  const skip = new Set([
    "date",
    "x-request-id",
    "set-cookie",
    "transfer-encoding",
    "connection",
    "keep-alive",
  ]);
  const out = {};
  for (const [key, value] of headers.entries()) {
    const k = key.toLowerCase();
    if (skip.has(k)) continue;
    if (k in out) {
      out[k] = [].concat(out[k], value);
    } else {
      out[k] = value;
    }
  }
  return out;
}

function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

/**
 * Extract the resource_metadata parameter from a WWW-Authenticate header
 * value. Returns the raw parameter value or null when absent.
 */
function extractResourceMetadata(wwwAuthenticate) {
  if (typeof wwwAuthenticate !== "string") return null;
  const m = wwwAuthenticate.match(/resource_metadata\s*=\s*"([^"]*)"/i);
  if (m) return m[1];
  const bare = wwwAuthenticate.match(/resource_metadata\s*=\s*([^\s,]+)/i);
  if (bare) return bare[1];
  return null;
}

/**
 * A1: an unauthenticated JSON-RPC initialize request must receive HTTP 401
 * (an OAuth challenge), not a protocol-dispatch error.
 */
function assertA1(resp) {
  const violations = [];
  if (resp.status !== 401) {
    const detail = [];
    if (resp.bodyJsonParseError !== null) {
      detail.push(`body is not valid JSON (${resp.bodyJsonParseError})`);
    } else if (isPlainObject(resp.bodyJson) && resp.bodyJson.error) {
      const e = resp.bodyJson.error;
      detail.push(
        `JSON-RPC error ${e.code !== undefined ? e.code : "?"}: ${e.message || "(no message)"}`
      );
    }
    violations.push(
      `A1: unauthenticated initialize returned HTTP ${resp.status}${
        detail.length > 0 ? ` (${detail.join("; ")})` : ""
      }; expected HTTP 401 (OAuth challenge), not a protocol-dispatch error`
    );
  }
  return violations;
}

/**
 * A2: the 401 challenge must carry a Bearer WWW-Authenticate header whose
 * resource_metadata parameter is the configured public protected-resource
 * metadata URL, and never a loopback or lab URL.
 */
function assertA2(resp, expectedUrl, expectedIsLoopback) {
  const violations = [];
  const www = resp.headers["www-authenticate"];
  if (www === undefined) {
    violations.push(
      "A2: 401 response has no WWW-Authenticate header; expected a Bearer challenge with a resource_metadata parameter"
    );
    return violations;
  }
  if (!/^Bearer\s/i.test(www)) {
    violations.push(
      `A2: WWW-Authenticate is not a Bearer challenge: ${JSON.stringify(www)}`
    );
    return violations;
  }
  const resourceMetadata = extractResourceMetadata(www);
  if (resourceMetadata === null) {
    violations.push(
      `A2: Bearer challenge has no resource_metadata parameter: ${JSON.stringify(www)}`
    );
    return violations;
  }
  if (resourceMetadata !== expectedUrl) {
    violations.push(
      `A2: challenge resource_metadata is ${JSON.stringify(resourceMetadata)}; expected the configured public URL ${JSON.stringify(expectedUrl)}`
    );
  }
  if (!expectedIsLoopback) {
    if (isLoopbackUrl(resourceMetadata)) {
      violations.push(
        `A2: challenge resource_metadata points at a loopback/lab URL (${JSON.stringify(resourceMetadata)}); it must be the public URL`
      );
    }
    try {
      if (new URL(resourceMetadata).protocol !== "https:") {
        violations.push(
          `A2: challenge resource_metadata is not HTTPS: ${JSON.stringify(resourceMetadata)}`
        );
      }
    } catch {
      violations.push(
        `A2: challenge resource_metadata is not an absolute URL: ${JSON.stringify(resourceMetadata)}`
      );
    }
  }
  return violations;
}

/**
 * A3: the protected-resource metadata document must parse as JSON and name
 * the configured authorization-server issuer.
 */
function assertA3(doc, issuer) {
  const violations = [];
  if (doc.status !== 200) {
    violations.push(
      `A3: protected-resource metadata returned HTTP ${doc.status}; expected 200`
    );
    return violations;
  }
  if (doc.bodyJsonParseError !== null) {
    violations.push(
      `A3: protected-resource metadata is not valid JSON: ${doc.bodyJsonParseError}`
    );
    return violations;
  }
  if (!isPlainObject(doc.bodyJson)) {
    violations.push("A3: protected-resource metadata is not a JSON object");
    return violations;
  }
  const servers = doc.bodyJson.authorization_servers;
  if (!Array.isArray(servers) || servers.length === 0) {
    violations.push(
      "A3: protected-resource metadata has no non-empty authorization_servers array"
    );
    return violations;
  }
  if (!servers.every((s) => typeof s === "string")) {
    violations.push(
      "A3: protected-resource metadata authorization_servers contains non-string entries"
    );
  }
  if (!servers.includes(issuer)) {
    violations.push(
      `A3: protected-resource metadata authorization_servers ${JSON.stringify(servers)} does not name the configured issuer ${JSON.stringify(issuer)}`
    );
  }
  return violations;
}

/**
 * A4: the authorization-server metadata document must parse as JSON and
 * supply usable authorization, token, registration, and JWKS endpoints.
 */
function assertA4(doc, issuer, issuerIsLoopback) {
  const violations = [];
  if (doc.status !== 200) {
    violations.push(
      `A4: authorization-server metadata at ${doc.url} returned HTTP ${doc.status}; expected 200`
    );
    return violations;
  }
  if (doc.bodyJsonParseError !== null) {
    const snippet = (doc.bodyRaw || "").replace(/\s+/g, " ").slice(0, 80);
    violations.push(
      `A4: authorization-server metadata at ${doc.url} is not valid JSON (${doc.bodyJsonParseError}); body starts with ${JSON.stringify(snippet)}`
    );
    return violations;
  }
  if (!isPlainObject(doc.bodyJson)) {
    violations.push(
      `A4: authorization-server metadata at ${doc.url} is not a JSON object`
    );
    return violations;
  }
  const meta = doc.bodyJson;
  for (const key of [
    "authorization_endpoint",
    "token_endpoint",
    "registration_endpoint",
    "jwks_uri",
  ]) {
    const value = meta[key];
    if (typeof value !== "string" || value.length === 0) {
      violations.push(
        `A4: authorization-server metadata at ${doc.url} is missing a usable ${key}`
      );
      continue;
    }
    let parsed;
    try {
      parsed = new URL(value);
    } catch {
      violations.push(
        `A4: ${key} is not an absolute URL: ${JSON.stringify(value)}`
      );
      continue;
    }
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      violations.push(
        `A4: ${key} does not use http or https: ${JSON.stringify(value)}`
      );
      continue;
    }
    if (!issuerIsLoopback && parsed.protocol !== "https:") {
      violations.push(
        `A4: ${key} is not HTTPS for a public issuer: ${JSON.stringify(value)}`
      );
    }
  }
  return violations;
}

/**
 * Serialize a value to deterministic JSON (object keys sorted recursively).
 */
function deterministicStringify(value) {
  function sort(value) {
    if (Array.isArray(value)) return value.map(sort);
    if (isPlainObject(value)) {
      const out = {};
      for (const key of Object.keys(value).sort()) {
        out[key] = sort(value[key]);
      }
      return out;
    }
    return value;
  }
  return JSON.stringify(sort(value), null, 2);
}

function writeRecord(cfg, record) {
  fs.mkdirSync(cfg.recordDir, { recursive: true });
  const recordPath = path.join(cfg.recordDir, "mcp-acceptance-discovery.json");
  const envelope = {
    harness: HARNESS_NAME,
    harnessVersion: HARNESS_VERSION,
    phase: "0.2-discovery",
    target: cfg.url,
    issuer: cfg.issuer,
    recordedBy: "discovery-probe",
    record,
  };
  fs.writeFileSync(recordPath, deterministicStringify(envelope) + "\n", "utf8");
  return recordPath;
}

async function main() {
  const flags = parseArgs(process.argv.slice(2));

  if (flags.help) {
    printHelp();
    return 0;
  }

  if (flags._unknown.length > 0) {
    console.error(
      `[mcp-acceptance] CONFIG ERROR: unknown argument(s): ${flags._unknown.join(", ")}`
    );
    console.error("[mcp-acceptance] Run with --help for usage.");
    return 2;
  }

  let cfg;
  try {
    cfg = loadConfig(flags);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] CONFIG ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }

  const expectedResourceUrl = expectedResourceMetadataUrl(cfg.url);
  const expectedIsLoopback = isLoopbackUrl(expectedResourceUrl);
  const issuerIsLoopback = isLoopbackUrl(cfg.issuer);

  console.log(`[mcp-acceptance] target: ${cfg.url}`);
  console.log(`[mcp-acceptance] issuer: ${cfg.issuer}`);
  console.log(`[mcp-acceptance] expected resource_metadata: ${expectedResourceUrl}`);

  const record = {
    assertions: {},
  };

  // A1 + A2: unauthenticated initialize must receive the public 401 challenge.
  let initializeResp;
  try {
    initializeResp = await httpProbe(
      cfg,
      "POST",
      cfg.url,
      buildInitializeRequest()
    );
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.initialize = {
    request: buildInitializeRequest(),
    response: initializeResp,
  };

  const a1 = assertA1(initializeResp);
  const a2 = assertA2(initializeResp, expectedResourceUrl, expectedIsLoopback);
  record.assertions.A1 = { pass: a1.length === 0, violations: a1 };
  record.assertions.A2 = { pass: a2.length === 0, violations: a2 };

  // A3: the configured public protected-resource metadata document.
  let resourceDoc;
  try {
    resourceDoc = await httpProbe(cfg, "GET", expectedResourceUrl, null);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  resourceDoc.url = expectedResourceUrl;
  record.protectedResourceMetadata = {
    url: expectedResourceUrl,
    response: resourceDoc,
  };
  const a3 = assertA3(resourceDoc, cfg.issuer);
  record.assertions.A3 = { pass: a3.length === 0, violations: a3 };

  // A4: the authorization-server metadata document. Prefer the RFC 8414
  // location; fall back to the OIDC discovery location where appropriate.
  const asCandidates = [
    `${cfg.issuer.replace(/\/$/, "")}/.well-known/oauth-authorization-server`,
    `${cfg.issuer.replace(/\/$/, "")}/.well-known/openid-configuration`,
  ];
  let asDoc = null;
  const asAttempts = [];
  for (const candidate of asCandidates) {
    let doc;
    try {
      doc = await httpProbe(cfg, "GET", candidate, null);
    } catch (err) {
      if (err instanceof HarnessError) {
        console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
        return 2;
      }
      throw err;
    }
    doc.url = candidate;
    asAttempts.push(doc);
    if (doc.status === 200 && doc.bodyJsonParseError === null && isPlainObject(doc.bodyJson)) {
      asDoc = doc;
      break;
    }
  }
  record.authorizationServerMetadata = {
    attempts: asAttempts,
    used: asDoc ? asDoc.url : null,
  };
  const a4 = asDoc === null
    ? [
        `A4: no authorization-server metadata document found; tried ${asCandidates.join(", ")} (all non-200 or non-JSON)`,
      ]
    : assertA4(asDoc, cfg.issuer, issuerIsLoopback);
  record.assertions.A4 = { pass: a4.length === 0, violations: a4 };

  let recordPath = null;
  try {
    recordPath = writeRecord(cfg, record);
  } catch (err) {
    console.error(
      `[mcp-acceptance] WARNING: could not write record: ${describeError(err)}`
    );
  }

  const allViolations = [...a1, ...a2, ...a3, ...a4];
  for (const [id, list] of [
    ["A1", a1],
    ["A2", a2],
    ["A3", a3],
    ["A4", a4],
  ]) {
    if (list.length === 0) {
      console.log(`[mcp-acceptance] ${id}: PASS`);
    }
  }

  if (allViolations.length > 0) {
    console.log("");
    console.log("[mcp-acceptance] FAIL: public challenge / OAuth discovery is NOT compliant");
    for (const v of allViolations) {
      console.log(`  - ${v}`);
    }
    if (recordPath) {
      console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
    }
    console.log("");
    console.log(
      "[mcp-acceptance] This failure is the intentional Phase 0.2 baseline exit"
    );
    console.log(
      "[mcp-acceptance] condition: the current production component does not"
    );
    console.log(
      "[mcp-acceptance] issue a public 401 challenge or serve authorization-"
    );
    console.log(
      "[mcp-acceptance] server metadata."
    );
    return 1;
  }

  console.log("");
  console.log("[mcp-acceptance] PASS: public challenge and OAuth discovery are compliant");
  if (recordPath) {
    console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
  }
  return 0;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[mcp-acceptance] UNEXPECTED ERROR: ${describeError(err)}`);
    if (err && err.stack) {
      console.error(err.stack);
    }
    process.exitCode = 2;
  });

#!/usr/bin/env node
"use strict";

/**
 * Self-contained verification for the Phase 0.1 MCP acceptance harness.
 *
 * This script proves the harness behaves correctly on BOTH paths:
 *
 *   1. FAIL path — against a server that exhibits the CURRENT production
 *      behavior (initialize -> HTTP 400, JSON-RPC -32601), the harness must
 *      exit 1. This is the intentional Phase 0.1 baseline exit condition.
 *   2. PASS path — against a standards-compatible server, the harness must
 *      exit 0.
 *
 * It starts the verification-only mock server (mock/server.js) as a child
 * process, runs the harness (harness.js) as a child process against each
 * endpoint, asserts the expected exit codes, and cleans up the mock server.
 *
 * This is a test harness for the harness; it is not a release artifact and does
 * not touch production.
 *
 * Run:  node mcp-acceptance/verify.js
 * Exit: 0 if both paths behave as expected, 1 otherwise.
 */

const { spawn, execFile } = require("node:child_process");
const path = require("node:path");

const HERE = __dirname;
const MOCK = path.join(HERE, "mock", "server.js");
const HARNESS = path.join(HERE, "harness.js");

function flagValue(argv, name, fallback) {
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === `--${name}`) return argv[i + 1];
    if (arg.startsWith(`--${name}=`)) return arg.slice(name.length + 3);
  }
  const envVal = process.env[name.toUpperCase()];
  return envVal !== undefined && envVal !== "" ? envVal : fallback;
}

const PORT = Number(flagValue(process.argv.slice(2), "port", process.env.MOCK_PORT || 3999));
const BASE = `http://127.0.0.1:${PORT}`;

function log(msg) {
  console.log(`[verify] ${msg}`);
}

function runHarness(url) {
  return new Promise((resolve) => {
    execFile(
      process.execPath,
      [HARNESS, "--url", url, "--timeout-ms", "5000"],
      { timeout: 20000 },
      (error, stdout, stderr) => {
        // execFile sets error when the exit code is non-zero; error.code holds
        // the numeric exit status in that case.
        const exitCode =
          error === null ? 0 : typeof error.code === "number" ? error.code : -1;
        resolve({ exitCode, stdout, stderr });
      }
    );
  });
}

async function waitForServer(url, timeoutMs = 10000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url, { method: "POST", body: "{}" });
      // Any HTTP response (even 400/405) means the server is up.
      void res.status;
      await res.arrayBuffer();
      return true;
    } catch {
      // Not up yet; wait and retry.
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  return false;
}

async function main() {
  log(`starting mock server on ${BASE}`);
  const mock = spawn(process.execPath, [MOCK], {
    env: { ...process.env, MOCK_PORT: String(PORT) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let mockOutput = "";
  mock.stdout.on("data", (d) => {
    mockOutput += d.toString();
  });
  mock.stderr.on("data", (d) => {
    mockOutput += d.toString();
  });

  const cleanup = () => {
    if (mock.exitCode === null && mock.signalCode === null) {
      mock.kill("SIGTERM");
    }
  };
  process.on("exit", cleanup);
  process.on("SIGINT", () => {
    cleanup();
    process.exit(130);
  });

  const up = await waitForServer(`${BASE}/mcp-compliant`);
  if (!up) {
    log("ERROR: mock server did not become ready");
    log(mockOutput);
    cleanup();
    return 1;
  }
  log("mock server is ready");

  let allPassed = true;

  // 1. FAIL path: current-production behavior -> harness must exit 1.
  log("FAIL path: harness vs current-production behavior (expect exit 1)");
  const fail = await runHarness(`${BASE}/mcp-current`);
  const failOk = fail.exitCode === 1;
  log(`  harness exit code: ${fail.exitCode} (expected 1) -> ${failOk ? "OK" : "MISMATCH"}`);
  if (!failOk) allPassed = false;

  // 2. PASS path: standards-compatible behavior -> harness must exit 0.
  log("PASS path: harness vs standards-compatible server (expect exit 0)");
  const pass = await runHarness(`${BASE}/mcp-compliant`);
  const passOk = pass.exitCode === 0;
  log(`  harness exit code: ${pass.exitCode} (expected 0) -> ${passOk ? "OK" : "MISMATCH"}`);
  if (!passOk) allPassed = false;

  cleanup();

  log("");
  if (allPassed) {
    log("VERIFY PASS: harness exits 1 on current-production behavior and 0 on standards-compatible behavior.");
    return 0;
  }
  log("VERIFY FAIL: harness exit codes did not match expectations.");
  return 1;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[verify] UNEXPECTED ERROR: ${err && err.message ? err.message : String(err)}`);
    if (err && err.stack) console.error(err.stack);
    process.exitCode = 1;
  });

#!/usr/bin/env node
"use strict";

/**
 * Self-contained verification for the Phase 0.2 MCP discovery harness.
 *
 * This script proves discovery.js behaves correctly on BOTH paths:
 *
 *   1. FAIL path — against a server that exhibits the CURRENT production
 *      behavior (initialize -> HTTP 400, JSON-RPC -32601, no
 *      WWW-Authenticate), the harness must exit 1 with focused violations on
 *      A1 (401 challenge), A2 (public resource_metadata), and A4
 *      (authorization-server metadata), while A3 (protected-resource metadata
 *      naming the configured issuer) passes — matching the verified current
 *      production state in docs/MCP-PRODUCTION-FIX-PLAN.md.
 *   2. PASS path — against a server that issues the public 401 challenge and
 *      serves valid protected-resource and authorization-server metadata, the
 *      harness must exit 0.
 *
 * It starts the verification-only mock server (mock/server.js) as a child
 * process, runs the harness (discovery.js) as a child process against each
 * endpoint, asserts the expected exit codes and focused violations, and
 * cleans up the mock server.
 *
 * The mock mirrors production's two-host topology: the MCP host (MOCK_PORT,
 * default 3998) serves the MCP endpoint and the protected-resource metadata;
 * the issuer host (MOCK_PORT + 1) serves the authorization-server metadata
 * (SPA HTML in the current mode, valid JSON in the compliant mode).
 *
 * This is a test harness for the harness; it is not a release artifact and
 * does not touch production.
 *
 * Run:  node mcp-acceptance/verify-discovery.js
 * Exit: 0 if both paths behave as expected, 1 otherwise.
 */

const { spawn, execFile } = require("node:child_process");
const path = require("node:path");

const HERE = __dirname;
const MOCK = path.join(HERE, "mock", "server.js");
const HARNESS = path.join(HERE, "discovery.js");

function flagValue(argv, name, fallback) {
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === `--${name}`) return argv[i + 1];
    if (arg.startsWith(`--${name}=`)) return arg.slice(name.length + 3);
  }
  const envVal = process.env[name.toUpperCase()];
  return envVal !== undefined && envVal !== "" ? envVal : fallback;
}

const PORT = Number(flagValue(process.argv.slice(2), "port", process.env.MOCK_PORT || 3998));
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${PORT + 1}`;

function log(msg) {
  console.log(`[verify-discovery] ${msg}`);
}

function runHarness(url, issuer) {
  return new Promise((resolve) => {
    execFile(
      process.execPath,
      [HARNESS, "--url", url, "--issuer", issuer, "--timeout-ms", "5000"],
      { timeout: 20000 },
      (error, stdout, stderr) => {
        // execFile sets error when the exit code is non-zero; error.code holds
        // the numeric exit status in that case.
        const exitCode =
          error === null ? 0 : typeof error.code === "number" ? error.code : -1;
        resolve({ exitCode, stdout, stderr });
      }
    );
  });
}

async function waitForServer(url, timeoutMs = 10000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
      void res.status;
      await res.arrayBuffer();
      return true;
    } catch {
      // Not up yet; wait and retry.
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  return false;
}

async function main() {
  log(`starting mock server (MCP host ${MCP_BASE}, issuer host ${ISSUER_BASE})`);
  const mock = spawn(process.execPath, [MOCK], {
    env: { ...process.env, MOCK_PORT: String(PORT) },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let mockOutput = "";
  mock.stdout.on("data", (d) => {
    mockOutput += d.toString();
  });
  mock.stderr.on("data", (d) => {
    mockOutput += d.toString();
  });

  const cleanup = () => {
    if (mock.exitCode === null && mock.signalCode === null) {
      mock.kill("SIGTERM");
    }
  };
  process.on("exit", cleanup);
  process.on("SIGINT", () => {
    cleanup();
    process.exit(130);
  });

  const up =
    (await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`)) &&
    (await waitForServer(`${ISSUER_BASE}/.well-known/openid-configuration`));
  if (!up) {
    log("ERROR: mock server did not become ready");
    log(mockOutput);
    cleanup();
    return 1;
  }
  log("mock server is ready");

  let allPassed = true;
  const check = (label, ok) => {
    log(`  ${label} -> ${ok ? "OK" : "MISMATCH"}`);
    if (!ok) allPassed = false;
  };

  // 1. FAIL path: current-production behavior -> harness must exit 1 with
  //    focused A1/A2/A4 violations and a passing A3.
  log("FAIL path: harness vs current-production behavior (expect exit 1)");
  const fail = await runHarness(`${MCP_BASE}/mcp-discovery-current`, ISSUER_BASE);
  check(`harness exit code: ${fail.exitCode} (expected 1)`, fail.exitCode === 1);
  check(
    "violation A1 (401 challenge) present",
    fail.stdout.includes("A1:") && fail.stdout.includes("expected HTTP 401")
  );
  check(
    "violation A2 (public resource_metadata) present",
    fail.stdout.includes("A2:") && fail.stdout.includes("resource_metadata")
  );
  check(
    "violation A4 (authorization-server metadata) present",
    fail.stdout.includes("A4:")
  );
  check("A3 (protected-resource metadata issuer) passes", fail.stdout.includes("A3: PASS"));

  // 2. PASS path: compliant challenge + discovery -> harness must exit 0.
  log("PASS path: harness vs compliant discovery server (expect exit 0)");
  const pass = await runHarness(`${MCP_BASE}/mcp-discovery-compliant`, ISSUER_BASE);
  check(`harness exit code: ${pass.exitCode} (expected 0)`, pass.exitCode === 0);
  check("A1 passes", pass.stdout.includes("A1: PASS"));
  check("A2 passes", pass.stdout.includes("A2: PASS"));
  check("A3 passes", pass.stdout.includes("A3: PASS"));
  check("A4 passes", pass.stdout.includes("A4: PASS"));

  cleanup();

  log("");
  if (allPassed) {
    log("VERIFY PASS: discovery harness exits 1 on current-production behavior (A1/A2/A4 red, A3 green) and 0 on compliant behavior.");
    return 0;
  }
  log("VERIFY FAIL: discovery harness behavior did not match expectations.");
  return 1;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[verify-discovery] UNEXPECTED ERROR: ${err && err.message ? err.message : String(err)}`);
    if (err && err.stack) console.error(err.stack);
    process.exitCode = 1;
  });

#!/usr/bin/env node
"use strict";

/**
 * Verification-only mock MCP server for the Phase 0.1 and Phase 0.2
 * acceptance harnesses.
 *
 * This is NOT a release artifact and NOT the production component. It exists
 * solely to exercise the harnesses' PASS and FAIL paths deterministically.
 *
 * It mirrors production's two-host topology:
 *
 *   MCP host (MOCK_PORT, default 3999):
 *     POST /mcp-compliant  -> Phase 0.1 PASS: standards-compatible initialize
 *                             response (200)
 *     POST /mcp-current    -> Phase 0.1 FAIL: the CURRENT production behavior:
 *                             HTTP 400 with JSON-RPC error -32601 "Method not
 *                             found" (mirrors mcp-server/src/gateway.rs, which
 *                             only recognizes tools/list and tools/call)
 *     POST /mcp-discovery-compliant
 *                           -> Phase 0.2 PASS: initialize returns HTTP 401
 *                              with a Bearer WWW-Authenticate challenge whose
 *                              resource_metadata points at the MCP host's
 *                              well-known URL
 *     POST /mcp-discovery-current
 *                           -> Phase 0.2 FAIL: mirrors the CURRENT production
 *                              behavior: initialize returns HTTP 400 with
 *                              JSON-RPC -32601 and no WWW-Authenticate header
 *     GET /.well-known/oauth-protected-resource
 *                           -> RFC 9728 protected-resource metadata (valid
 *                              JSON in both modes, mirroring production where
 *                              the MCP host serves this document correctly),
 *                              naming the issuer host
 *
 *   Issuer host (MOCK_ISSUER_PORT, default MOCK_PORT + 1):
 *     GET /.well-known/oauth-authorization-server
 *                           -> RFC 8414 authorization-server metadata (valid
 *                              JSON with authorization, token, registration,
 *                              and JWKS endpoints) in the compliant mode;
 *                              CommonCal SPA HTML in the current mode
 *     GET /.well-known/openid-configuration
 *                           -> CommonCal SPA HTML (mirrors the verified
 *                              current state of cal.hajnal.space, which falls
 *                              through to the SPA ingress)
 *
 * The mode (current vs compliant) is set by the last discovery endpoint the
 * harness probes on the MCP host; the harness always probes initialize first,
 * so the mode is fixed before any metadata document is requested.
 *
 * Run:  node mcp-acceptance/mock/server.js
 * Env:  MOCK_PORT (default 3999), MOCK_ISSUER_PORT (default MOCK_PORT + 1)
 */

const http = require("node:http");

const PORT = Number(process.env.MOCK_PORT || 3999);
const ISSUER_PORT = Number(process.env.MOCK_ISSUER_PORT || PORT + 1);
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${ISSUER_PORT}`;

// "current" mirrors the verified current production state; "compliant"
// mirrors the target state. Set by the discovery endpoints on the MCP host.
let mode = null;

const SPA_HTML =
  '<!doctype html><html><head><meta charset="utf-8"><title>CommonCal</title></head><body><div id="root"></div><script src="/static/js/main.js"></script></body></html>';

function sendJson(res, status, body, headers = {}) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(payload),
    ...headers,
  });
  res.end(payload);
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    "Content-Type": "text/html; charset=utf-8",
    "Content-Length": Buffer.byteLength(html),
  });
  res.end(html);
}

function protectedResourceMetadata() {
  // Mirrors the production shape (mcp-server/src/config.rs
  // OauthProtectedResourceMetadata) with the mock MCP host as the resource
  // and the mock issuer host as the authorization server.
  return {
    resource: `${MCP_BASE}/mcp`,
    authorization_servers: [ISSUER_BASE],
    scopes_supported: [
      "commoncal.calendar.metadata.read",
      "commoncal.availability.read",
      "commoncal.event.read.basic",
      "commoncal.event.read.details",
      "commoncal.event.create",
      "commoncal.event.update",
      "commoncal.event.delete",
      "commoncal.reminder.read",
      "commoncal.reminder.write",
    ],
    dpop_bound_access_tokens: false,
  };
}

function authorizationServerMetadata() {
  // RFC 8414 authorization-server metadata with the four endpoints the
  // Phase 0.2 A4 assertion requires.
  return {
    issuer: ISSUER_BASE,
    authorization_endpoint: `${ISSUER_BASE}/authorize`,
    token_endpoint: `${ISSUER_BASE}/token`,
    registration_endpoint: `${ISSUER_BASE}/register`,
    jwks_uri: `${ISSUER_BASE}/jwks`,
    response_types_supported: ["code"],
    grant_types_supported: ["authorization_code"],
    code_challenge_methods_supported: ["S256"],
  };
}

const mcpServer = http.createServer((req, res) => {
  if (req.method === "GET") {
    if (req.url === "/.well-known/oauth-protected-resource") {
      sendJson(res, 200, protectedResourceMetadata());
      return;
    }
    sendJson(res, 404, { error: "not found" });
    return;
  }

  if (req.method !== "POST") {
    sendJson(res, 405, { error: "method not allowed" });
    return;
  }

  let raw = "";
  req.on("data", (chunk) => {
    raw += chunk;
  });
  req.on("end", () => {
    let message = null;
    try {
      message = JSON.parse(raw);
    } catch {
      message = null;
    }
    const method = message && message.method;
    const id = message ? message.id : null;

    if (req.url === "/mcp-discovery-compliant") {
      // Phase 0.2 PASS path: an unauthenticated initialize receives the
      // standards-compliant 401 challenge with a resource_metadata parameter
      // pointing at the MCP host's well-known URL (mirrors the lab's
      // challenge shape, slice1-lab/src/bin/mcp_echo.rs unauthorized()).
      mode = "compliant";
      if (method === "initialize") {
        sendJson(
          res,
          401,
          { error: { code: -2000, message: "authorization token is required" } },
          {
            "WWW-Authenticate":
              `Bearer realm="mcp", resource_metadata="${MCP_BASE}/.well-known/oauth-protected-resource", error="missing_token"`,
          }
        );
      } else {
        sendJson(res, 401, {
          jsonrpc: "2.0",
          id,
          error: { code: -2000, message: "authorization token is required" },
        });
      }
      return;
    }

    if (req.url === "/mcp-discovery-current") {
      // Phase 0.2 FAIL path: mirror the CURRENT production gateway — only
      // tools/list and tools/call are recognized; initialize (and everything
      // else) is HTTP 400 with JSON-RPC -32601 and no WWW-Authenticate header.
      // See mcp-server/src/gateway.rs.
      mode = "current";
      if (method === "tools/list" || method === "tools/call") {
        sendJson(res, 200, {
          jsonrpc: "2.0",
          id,
          result: { tools: [{ name: "calendar_list" }] },
        });
      } else {
        sendJson(res, 400, {
          jsonrpc: "2.0",
          id,
          error: { code: -32601, message: `Method not found: ${method}` },
        });
      }
      return;
    }

    if (req.url === "/mcp-compliant") {
      // Standards-compatible initialize response.
      if (method === "initialize") {
        sendJson(res, 200, {
          jsonrpc: "2.0",
          id,
          result: {
            protocolVersion: "2025-03-26",
            capabilities: { tools: {} },
            serverInfo: { name: "mock-standards-compliant", version: "1.0.0" },
          },
        });
      } else {
        sendJson(res, 200, {
          jsonrpc: "2.0",
          id,
          error: { code: -32601, message: `Method not found: ${method}` },
        });
      }
      return;
    }

    if (req.url === "/mcp-current") {
      // Mirror the CURRENT production gateway: only tools/list and tools/call
      // are recognized; everything else (including initialize) is -32601 with
      // HTTP 400. See mcp-server/src/gateway.rs.
      if (method === "tools/list" || method === "tools/call") {
        sendJson(res, 200, {
          jsonrpc: "2.0",
          id,
          result: { tools: [{ name: "calendar_list" }] },
        });
      } else {
        sendJson(res, 400, {
          jsonrpc: "2.0",
          id,
          error: { code: -32601, message: `Method not found: ${method}` },
        });
      }
      return;
    }

    sendJson(res, 404, { error: "not found" });
  });
});

const issuerServer = http.createServer((req, res) => {
  if (req.method !== "GET") {
    sendJson(res, 405, { error: "method not allowed" });
    return;
  }
  if (req.url === "/.well-known/oauth-authorization-server") {
    if (mode === "compliant") {
      sendJson(res, 200, authorizationServerMetadata());
    } else {
      // Current production: the issuer host is handled by core's "/" ingress
      // and falls through to the SPA (docs/MCP-PRODUCTION-FIX-PLAN.md).
      sendHtml(res, 200, SPA_HTML);
    }
    return;
  }
  if (req.url === "/.well-known/openid-configuration") {
    // Verified current state: cal.hajnal.space returns the CommonCal SPA
    // HTML, not authorization-server metadata.
    sendHtml(res, 200, SPA_HTML);
    return;
  }
  sendHtml(res, 200, SPA_HTML);
});

mcpServer.listen(PORT, "127.0.0.1", () => {
  console.log(`[mock-mcp] MCP host on http://127.0.0.1:${PORT}`);
  console.log(`[mock-mcp] compliant endpoint: http://127.0.0.1:${PORT}/mcp-compliant`);
  console.log(`[mock-mcp] current-production endpoint: http://127.0.0.1:${PORT}/mcp-current`);
  console.log(`[mock-mcp] discovery-compliant endpoint: http://127.0.0.1:${PORT}/mcp-discovery-compliant`);
  console.log(`[mock-mcp] discovery-current endpoint: http://127.0.0.1:${PORT}/mcp-discovery-current`);
});

issuerServer.listen(ISSUER_PORT, "127.0.0.1", () => {
  console.log(`[mock-mcp] issuer host on http://127.0.0.1:${ISSUER_PORT}`);
});

"use strict";

/**
 * Verification-only mock OAuth authorization server for the Phase 0.3
 * (oauth-lifecycle) and Phase 0.4 (security-isolation) acceptance harnesses.
 *
 * This is NOT a release artifact and NOT the production authorization server.
 * It exists solely to exercise the harnesses' PASS and FAIL paths
 * deterministically. It is a self-contained, dependency-free OAuth provider
 * (DCR + Authorization Code + S256 PKCE + token exchange + JWKS) built on
 * Node built-ins only.
 *
 * It reuses the slice1-lab fixture shapes:
 *   - the DCR request shape (slice1-lab/negative_tests.py fresh_dcr,
 *     slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata);
 *   - the standard access-token claim contract (slice1-lab/src/jwt.rs
 *     AccessClaims: iss, numeric sub, aud, exp, iat, client_id, scope, jti,
 *     amr);
 *   - the scope catalog (slice1-lab/src/common.rs SCOPE_CATALOG);
 *   - the negative-token / fail-closed cases (slice1-lab/negative_tests.py
 *     cases 3-9, slice1-lab/PROOF.md P7).
 *
 * It does NOT import lab code and does NOT launch the lab binaries. It owns
 * its own signing key (generated at startup), its own client/code/token
 * stores, and its own grant store.
 */

const crypto = require("node:crypto");

// ---------------------------------------------------------------------------
// Scope catalog (reused from slice1-lab/src/common.rs SCOPE_CATALOG)
// ---------------------------------------------------------------------------

const SCOPE_CATALOG = [
  "commoncal.calendar.metadata.read",
  "commoncal.availability.read",
  "commoncal.event.read.basic",
  "commoncal.event.read.details",
  "commoncal.event.create",
  "commoncal.event.update",
  "commoncal.event.delete",
  "commoncal.reminder.read",
  "commoncal.reminder.write",
];

// A scope deliberately outside the catalog (slice1-lab/src/common.rs EVIL_SCOPE).
const EVIL_SCOPE = "evil.unknown.scope";

// ---------------------------------------------------------------------------
// base64url helpers
// ---------------------------------------------------------------------------

function b64urlEncode(buf) {
  return Buffer.from(buf).toString("base64url");
}

function b64urlDecode(str) {
  return Buffer.from(str, "base64url");
}

function b64urlJson(obj) {
  return b64urlEncode(JSON.stringify(obj));
}

// ---------------------------------------------------------------------------
// RSA key + JWK + RS256 JWT
// ---------------------------------------------------------------------------

/**
 * Generate an RSA key pair and expose the public key as a JWK (n, e) plus a
 * signing function. The private key never leaves this module.
 */
function createSigningKey(kid) {
  const { publicKey, privateKey } = crypto.generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: { type: "spki", format: "pem" },
    privateKeyEncoding: { type: "pkcs8", format: "pem" },
  });

  // Extract n and e from the SPKI public key.
  const keyObj = crypto.createPublicKey(publicKey);
  const jwk = keyObj.export({ format: "jwk" });

  return {
    kid,
    jwk: {
      kty: "RSA",
      n: jwk.n,
      e: jwk.e,
      use: "sig",
      alg: "RS256",
      kid,
    },
    sign(payload) {
      const signer = crypto.createSign("RSA-SHA256");
      signer.update(payload);
      signer.end();
      // Output encoding is base64url; the signature format is DER (PKCS#1 v1.5),
      // which is what RSA-SHA256 produces by default.
      return signer.sign(privateKey, "base64url");
    },
  };
}

/**
 * Sign a JWT (RS256) with the given claims and signing key.
 */
function signJwt(claims, signingKey) {
  const header = { alg: "RS256", typ: "JWT", kid: signingKey.kid };
  const signingInput = `${b64urlJson(header)}.${b64urlJson(claims)}`;
  const signature = signingKey.sign(signingInput);
  return `${signingInput}.${signature}`;
}

/**
 * Verify an RS256 JWT signature against a JWK. Returns true if valid.
 */
function verifyJwtSignature(jwt, jwk) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return false;
  const [headerB64, payloadB64, signatureB64] = parts;
  let header;
  try {
    header = JSON.parse(b64urlDecode(headerB64).toString("utf8"));
  } catch {
    return false;
  }
  if (header.alg !== "RS256") return false;
  if (jwk.kty !== "RSA" || !jwk.n || !jwk.e) return false;

  // Reconstruct the RSA public key from the JWK (n, e). Node handles the
  // modulus padding internally for the JWK->key conversion.
  let publicKey;
  try {
    publicKey = crypto.createPublicKey({
      key: { kty: "RSA", n: jwk.n, e: jwk.e },
      format: "jwk",
    });
  } catch {
    return false;
  }

  const verifier = crypto.createVerify("RSA-SHA256");
  verifier.update(`${headerB64}.${payloadB64}`);
  verifier.end();
  try {
    // Pass the signature as a Buffer (default 'buffer' format).
    return verifier.verify(publicKey, b64urlDecode(signatureB64));
  } catch {
    return false;
  }
}

/**
 * Decode a JWT payload (no signature verification). Returns the claims object
 * or null.
 */
function decodeJwtPayload(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[1]).toString("utf8"));
  } catch {
    return null;
  }
}

/**
 * Decode a JWT header (no signature verification). Returns the header object
 * or null.
 */
function decodeJwtHeader(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[0]).toString("utf8"));
  } catch {
    return null;
  }
}

// ---------------------------------------------------------------------------
// PKCE S256
// ---------------------------------------------------------------------------

/**
 * Compute the S256 code challenge for a verifier (RFC 7636).
 */
function s256Challenge(verifier) {
  return b64urlEncode(crypto.createHash("sha256").update(verifier).digest());
}

// ---------------------------------------------------------------------------
// The mock OAuth provider
// ---------------------------------------------------------------------------

/**
 * A self-contained mock OAuth authorization server.
 *
 * @param {object} opts
 * @param {string} opts.issuer      The issuer base URL (e.g. http://127.0.0.1:PORT).
 * @param {string} opts.resource    The exact MCP resource / audience.
 * @param {string} opts.redirect    The admitted loopback redirect URI.
 * @param {string} [opts.kid]       The signing key id.
 */
class MockOAuthProvider {
  constructor({ issuer, resource, redirect, kid = "mcp-acceptance-rs256" }) {
    this.issuer = issuer.replace(/\/$/, "");
    this.resource = resource;
    this.redirect = redirect;
    this.signingKey = createSigningKey(kid);

    // Stores.
    this.clients = new Map(); // client_id -> client metadata
    this.codes = new Map(); // code -> { client_id, redirect_uri, challenge, scope, sub, used }
    this.tokens = new Map(); // jti -> { client_id, sub, scope, aud, exp, iat }
    this.grants = new Map(); // `${sub}:${client_id}` -> grant

    this.clientSeq = 0;
  }

  // -- DCR ------------------------------------------------------------------

  /**
   * Handle a DCR (RFC 7591) registration request. Mirrors the lab's DCR
   * policy (slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata):
   * exactly one loopback redirect, grant_types [authorization_code,
   * refresh_token], response_types [code], token_endpoint_auth_method none.
   *
   * @returns {{status: number, body: object}}
   */
  handleRegister(body) {
    const redirectUris = body.redirect_uris;
    if (!Array.isArray(redirectUris) || redirectUris.length !== 1) {
      return { status: 400, body: { error: "invalid_redirect_uris" } };
    }
    if (redirectUris[0] !== this.redirect) {
      return {
        status: 400,
        body: {
          error: "invalid_redirect_uri",
          error_description: `only the admitted loopback ${this.redirect} is allowed`,
        },
      };
    }
    const grantTypes = Array.isArray(body.grant_types) ? [...body.grant_types].sort() : [];
    if (
      JSON.stringify(grantTypes) !==
      JSON.stringify(["authorization_code", "refresh_token"])
    ) {
      return { status: 400, body: { error: "invalid_grant_types" } };
    }
    const responseTypes = Array.isArray(body.response_types) ? body.response_types : [];
    if (responseTypes.length !== 1 || responseTypes[0] !== "code") {
      return { status: 400, body: { error: "invalid_response_types" } };
    }
    if (body.token_endpoint_auth_method !== "none") {
      return { status: 400, body: { error: "invalid_token_endpoint_auth_method" } };
    }

    this.clientSeq += 1;
    const client_id = `mcp-acceptance-client-${this.clientSeq}`;
    const client = {
      client_id,
      client_name: body.client_name ?? "mcp-acceptance",
      redirect_uris: [this.redirect],
      grant_types: ["authorization_code", "refresh_token"],
      response_types: ["code"],
      token_endpoint_auth_method: "none",
      scope: body.scope ?? SCOPE_CATALOG.join(" "),
    };
    this.clients.set(client_id, client);
    return { status: 201, body: client };
  }

  // -- Authorization --------------------------------------------------------

  /**
   * Handle an authorization request. In the mock, login + consent are
   * auto-approved (the lab's stub adapter / CommonCal consent is the identity
   * authority; the mock stands in for it). It issues an authorization code
   * bound to the client, redirect URI, PKCE challenge, scope, and subject.
   *
   * @param {object} params  URLSearchParams of the authorization request.
   * @returns {{status: number, body: object, location?: string}}
   */
  handleAuthorize(params) {
    const client_id = params.get("client_id");
    const client = this.clients.get(client_id);
    if (!client) {
      return { status: 400, body: { error: "unknown_client" } };
    }
    const redirect_uri = params.get("redirect_uri");
    if (redirect_uri !== this.redirect) {
      return { status: 400, body: { error: "invalid_redirect_uri" } };
    }
    const response_type = params.get("response_type");
    if (response_type !== "code") {
      return { status: 400, body: { error: "unsupported_response_type" } };
    }
    const code_challenge = params.get("code_challenge");
    const code_challenge_method = params.get("code_challenge_method");
    if (!code_challenge || code_challenge_method !== "S256") {
      return { status: 400, body: { error: "invalid_request", error_description: "S256 PKCE required" } };
    }
    const scope = params.get("scope") ?? "";
    const state = params.get("state") ?? "";

    // The subject is a CommonCal user id (numeric). The mock stands in for
    // CommonCal's identity authority and binds the fixed lab subject "1".
    const sub = "1";

    const code = `mcp-acceptance-code-${crypto.randomBytes(12).toString("hex")}`;
    this.codes.set(code, {
      client_id,
      redirect_uri,
      challenge: code_challenge,
      scope,
      sub,
      used: false,
    });

    const location = `${this.redirect}?code=${encodeURIComponent(code)}&state=${encodeURIComponent(state)}`;
    return { status: 302, body: {}, location };
  }

  // -- Token ----------------------------------------------------------------

  /**
   * Handle a token exchange (Authorization Code + S256 PKCE). Verifies the
   * code, the PKCE verifier, and the redirect URI, then issues a JWT access
   * token with the standard claim contract.
   *
   * @param {object} params  URLSearchParams of the token request.
   * @returns {{status: number, body: object}}
   */
  handleToken(params) {
    const grant_type = params.get("grant_type");
    if (grant_type !== "authorization_code") {
      return { status: 400, body: { error: "unsupported_grant_type" } };
    }
    const code = params.get("code");
    const entry = this.codes.get(code);
    if (!entry) {
      return { status: 400, body: { error: "invalid_grant", error_description: "unknown or expired code" } };
    }
    if (entry.used) {
      return { status: 400, body: { error: "invalid_grant", error_description: "code already redeemed" } };
    }
    const client_id = params.get("client_id");
    if (client_id !== entry.client_id) {
      return { status: 400, body: { error: "invalid_grant", error_description: "client_id mismatch" } };
    }
    const redirect_uri = params.get("redirect_uri");
    if (redirect_uri !== entry.redirect_uri) {
      return { status: 400, body: { error: "invalid_grant", error_description: "redirect_uri mismatch" } };
    }
    const code_verifier = params.get("code_verifier");
    if (!code_verifier) {
      return { status: 400, body: { error: "invalid_request", error_description: "code_verifier required" } };
    }
    if (s256Challenge(code_verifier) !== entry.challenge) {
      return { status: 400, body: { error: "invalid_grant", error_description: "PKCE verifier mismatch" } };
    }

    entry.used = true;

    // The granted scopes are the intersection of requested and catalog
    // (slice1-lab/auth-server/src/server.mjs approvedResourceScopes).
    const requested = new Set(String(entry.scope).split(" ").filter(Boolean));
    const granted = SCOPE_CATALOG.filter((s) => requested.has(s));

    const now = Math.floor(Date.now() / 1000);
    const jti = `mcp-acceptance-jti-${crypto.randomBytes(12).toString("hex")}`;
    const claims = {
      iss: this.issuer,
      sub: entry.sub,
      aud: this.resource,
      exp: now + 300,
      iat: now,
      jti,
      client_id: entry.client_id,
      scope: granted.join(" "),
      amr: ["pwd"],
    };
    const access_token = signJwt(claims, this.signingKey);
    this.tokens.set(jti, {
      client_id: entry.client_id,
      sub: entry.sub,
      scope: granted.join(" "),
      aud: this.resource,
      exp: claims.exp,
      iat: now,
    });

    return {
      status: 200,
      body: {
        access_token,
        token_type: "Bearer",
        expires_in: 300,
        refresh_token: `mcp-acceptance-refresh-${crypto.randomBytes(12).toString("hex")}`,
        scope: granted.join(" "),
      },
    };
  }

  // -- JWKS -----------------------------------------------------------------

  /**
   * The JWKS document (public key only).
   */
  jwks() {
    return { keys: [this.signingKey.jwk] };
  }

  // -- Token validation (resource-server side) ------------------------------

  /**
   * Validate an access token the way the production MCP server must:
   * signature (via JWKS), exact iss, exact aud, exp, and the standard claims.
   * Returns { ok, claims?, error? }.
   */
  validateAccessToken(token) {
    if (typeof token !== "string" || token.split(".").length !== 3) {
      return { ok: false, error: "malformed_token" };
    }
    const header = decodeJwtHeader(token);
    if (!header || header.alg !== "RS256") {
      return { ok: false, error: "unsupported_alg" };
    }
    const kid = header.kid;
    if (kid !== this.signingKey.kid) {
      return { ok: false, error: "unknown_kid" };
    }
    if (!verifyJwtSignature(token, this.signingKey.jwk)) {
      return { ok: false, error: "invalid_signature" };
    }
    const claims = decodeJwtPayload(token);
    if (!claims) {
      return { ok: false, error: "malformed_payload" };
    }
    if (claims.iss !== this.issuer) {
      return { ok: false, error: "invalid_issuer" };
    }
    const aud = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
    if (!aud.includes(this.resource)) {
      return { ok: false, error: "invalid_audience" };
    }
    const now = Math.floor(Date.now() / 1000);
    if (typeof claims.exp !== "number" || claims.exp <= now) {
      return { ok: false, error: "token_expired" };
    }
    if (typeof claims.sub !== "string" || !/^\d+$/.test(claims.sub)) {
      return { ok: false, error: "invalid_sub" };
    }
    if (typeof claims.client_id !== "string" || !this.clients.has(claims.client_id)) {
      return { ok: false, error: "unknown_client" };
    }
    return { ok: true, claims };
  }

  // -- Grants ---------------------------------------------------------------

  /**
   * Create an active grant for (sub, client_id) with the given allowed
   * calendar ids and scopes. Mirrors slice1-lab/src/bin/commoncal.rs
   * upsert_grant (replace semantics).
   */
  upsertGrant(sub, client_id, allowedCalendarIds, scopes) {
    const key = `${sub}:${client_id}`;
    this.grants.set(key, {
      sub,
      client_id,
      allowed_calendar_ids: allowedCalendarIds,
      scopes,
      revoked: false,
    });
  }

  /**
   * Revoke the active grant for (sub, client_id).
   */
  revokeGrant(sub, client_id) {
    const key = `${sub}:${client_id}`;
    const grant = this.grants.get(key);
    if (grant) grant.revoked = true;
  }

  /**
   * Get the active grant for (sub, client_id), or null.
   */
  getActiveGrant(sub, client_id) {
    const grant = this.grants.get(`${sub}:${client_id}`);
    if (!grant || grant.revoked) return null;
    return grant;
  }
}

module.exports = {
  MockOAuthProvider,
  SCOPE_CATALOG,
  EVIL_SCOPE,
  b64urlEncode,
  b64urlDecode,
  b64urlJson,
  createSigningKey,
  signJwt,
  verifyJwtSignature,
  decodeJwtPayload,
  decodeJwtHeader,
  s256Challenge,
};

